function loadReportsPage() {
    const startInput = document.getElementById('report-start-date');
    const endInput = document.getElementById('report-end-date');
    const now = new Date();
    const firstDay = new Date(now.getFullYear(), now.getMonth(), 1);
    
    if (startInput) startInput.value = firstDay.toISOString().split('T')[0];
    if (endInput) endInput.value = now.toISOString().split('T')[0];
}

function generateReport() {
    const startStr = document.getElementById('report-start-date')?.value;
    const endStr = document.getElementById('report-end-date')?.value;
    const type = document.getElementById('report-type')?.value;
    
    if (!startStr || !endStr) {
        showToast('Pilih rentang tanggal!', 'warning');
        return;
    }
    
    const startDate = new Date(startStr);
    const endDate = new Date(endStr);
    endDate.setHours(23, 59, 59);
    
    const transactions = getData('lpq_transactions') || [];
    let filtered = transactions.filter(t => {
        const d = new Date(t.date);
        const inRange = d >= startDate && d <= endDate;
        if (!inRange) return false;
        if (type === 'comprehensive' || type === 'cashflow') return true;
        return t.type === type;
    });
    
    filtered.sort((a, b) => new Date(a.date) - new Date(b.date));
    
    let totalIncome = 0, totalExpense = 0;
    const incomeCatTotals = {}, expenseCatTotals = {};
    
    const incTbody = document.getElementById('report-income-tbody');
    const expTbody = document.getElementById('report-expense-tbody');
    if (incTbody) incTbody.innerHTML = '';
    if (expTbody) expTbody.innerHTML = '';
    
    let incNum = 0, expNum = 0;
    
    filtered.forEach(t => {
        const tr = document.createElement('tr');
        
        if (t.type === 'income') {
            incNum++;
            totalIncome += Number(t.amount);
            incomeCatTotals[t.category] = (incomeCatTotals[t.category] || 0) + Number(t.amount);
            tr.innerHTML = `
                <td>${incNum}</td>
                <td>${formatDate(t.date)}</td>
                <td>${t.description}</td>
                <td>${t.category}</td>
                <td class="text-right">${formatCurrency(t.amount)}</td>
            `;
            if (incTbody) incTbody.appendChild(tr);
        } else {
            expNum++;
            totalExpense += Number(t.amount);
            expenseCatTotals[t.category] = (expenseCatTotals[t.category] || 0) + Number(t.amount);
            tr.innerHTML = `
                <td>${expNum}</td>
                <td>${formatDate(t.date)}</td>
                <td>${t.description}</td>
                <td>${t.category}</td>
                <td class="text-right">${formatCurrency(t.amount)}</td>
            `;
            if (expTbody) expTbody.appendChild(tr);
        }
    });
    
    if (incTbody && incTbody.children.length === 0) incTbody.innerHTML = '<tr><td colspan="5" class="text-center">Tidak ada data</td></tr>';
    if (expTbody && expTbody.children.length === 0) expTbody.innerHTML = '<tr><td colspan="5" class="text-center">Tidak ada data</td></tr>';
    
    const elTotInc = document.getElementById('report-total-income');
    const elTotExp = document.getElementById('report-total-expense');
    const elNet = document.getElementById('report-net');
    
    if (elTotInc) elTotInc.textContent = formatCurrency(totalIncome);
    if (elTotExp) elTotExp.textContent = formatCurrency(totalExpense);
    if (elNet) {
        const net = totalIncome - totalExpense;
        elNet.textContent = formatCurrency(net);
        elNet.className = net < 0 ? 'text-danger font-weight-bold' : 'text-success font-weight-bold';
    }
    
    const reportContent = document.getElementById('report-content');
    if (reportContent) reportContent.style.display = 'block';
    
    window.currentReportData = { startDate, endDate, filtered, totalIncome, totalExpense, incomeCatTotals, expenseCatTotals };
    
    renderReportChart(incomeCatTotals, expenseCatTotals);
    showToast('Laporan berhasil dibuat!');
}

function renderReportChart(incomeData, expenseData) {
    const ctx = document.getElementById('report-chart');
    if (!ctx || typeof Chart === 'undefined') return;
    
    if (window.myCharts && window.myCharts.report) window.myCharts.report.destroy();
    
    const labels = [...new Set([...Object.keys(incomeData), ...Object.keys(expenseData)])];
    const incArr = labels.map(l => incomeData[l] || 0);
    const expArr = labels.map(l => expenseData[l] || 0);
    
    window.myCharts = window.myCharts || {};
    window.myCharts.report = new Chart(ctx, {
        type: 'bar',
        data: {
            labels: labels,
            datasets: [
                { label: 'Pemasukan', backgroundColor: '#2e7d32', data: incArr },
                { label: 'Pengeluaran', backgroundColor: '#d32f2f', data: expArr }
            ]
        },
        options: { responsive: true, maintainAspectRatio: false }
    });
}



async function exportToExcel() {
    if (typeof ExcelJS === 'undefined') { showToast('Library ExcelJS tidak ditemukan!', 'error'); return; }
    const data = window.currentReportData;
    if (!data) { showToast('Buat laporan terlebih dahulu!', 'warning'); return; }
    
    showToast('Sedang menyiapkan file Excel...', 'info');
    
    const workbook = new ExcelJS.Workbook();
    workbook.creator = "LPQ Baitul Ma'sum";
    workbook.created = new Date();
    
    let logoId = null;
    try {
        const base64Data = "data:image/png;base64,";
        logoId = workbook.addImage({
            base64: base64Data,
            extension: 'png',
        });
    } catch (e) {
        console.error('Failed to load logo for Excel', e);
    }
    
    const sheet = workbook.addWorksheet('Laporan Keuangan');
    
    if (logoId !== null) {
        sheet.addImage(logoId, {
            tl: { col: 1, row: 1 },
            ext: { width: 100, height: 100 }
        });
    }
    
    sheet.mergeCells('D2:G2');
    sheet.getCell('D2').value = 'LAPORAN KEUANGAN';
    sheet.getCell('D2').font = { size: 16, bold: true };
    sheet.getCell('D2').alignment = { vertical: 'middle', horizontal: 'center' };
    
    sheet.mergeCells('D3:G3');
    sheet.getCell('D3').value = "LPQ BAITUL MA'SUM";
    sheet.getCell('D3').font = { size: 14, bold: true };
    sheet.getCell('D3').alignment = { vertical: 'middle', horizontal: 'center' };
    
    sheet.mergeCells('D4:G4');
    sheet.getCell('D4').value = 'Periode: ' + formatDate(data.startDate) + ' s/d ' + formatDate(data.endDate);
    sheet.getCell('D4').alignment = { vertical: 'middle', horizontal: 'center' };
    
    let currentRow = 8;
    
    const incHeaderRow = sheet.getRow(currentRow);
    incHeaderRow.values = ['', 'No', 'Tanggal', 'Keterangan', 'Kategori', 'Sumber Dana', 'Pemasukan', 'Pengeluaran'];
    incHeaderRow.font = { bold: true, color: { argb: 'FFFFFFFF' } };
    incHeaderRow.eachCell((cell, colNumber) => {
        if(colNumber > 1) {
            cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF2E7D32' } };
            cell.border = { top: { style: 'thin' }, left: { style: 'thin' }, bottom: { style: 'thin' }, right: { style: 'thin' } };
        }
    });
    
    currentRow++;
    
    let n = 1;
    let totalInc = 0;
    let totalExp = 0;
    
    const chronologicalData = [...data.filtered].sort((a, b) => new Date(a.date) - new Date(b.date));
    
    chronologicalData.forEach(t => {
        const row = sheet.getRow(currentRow);
        const amount = Number(t.amount);
        let inc = 0, exp = 0;
        
        if (t.type === 'income') { inc = amount; totalInc += amount; }
        else { exp = amount; totalExp += amount; }
        
        row.values = ['', n++, formatDate(t.date), t.description, t.category, t.wallet || '-', inc > 0 ? inc : '', exp > 0 ? exp : ''];
        row.getCell(7).numFmt = '"Rp"#,##0';
        row.getCell(8).numFmt = '"Rp"#,##0';
        
        row.eachCell((cell, colNum) => {
            if(colNum > 1) cell.border = { top: { style: 'thin' }, left: { style: 'thin' }, bottom: { style: 'thin' }, right: { style: 'thin' } };
        });
        currentRow++;
    });
    
    const totalRow = sheet.getRow(currentRow);
    totalRow.values = ['', '', '', '', '', 'TOTAL:', totalInc, totalExp];
    totalRow.font = { bold: true };
    totalRow.getCell(7).numFmt = '"Rp"#,##0';
    totalRow.getCell(8).numFmt = '"Rp"#,##0';
    
    sheet.getColumn(2).width = 5;
    sheet.getColumn(3).width = 15;
    sheet.getColumn(4).width = 30;
    sheet.getColumn(5).width = 20;
    sheet.getColumn(6).width = 20;
    sheet.getColumn(7).width = 20;
    sheet.getColumn(8).width = 20;
    
    try {
        const buffer = await workbook.xlsx.writeBuffer();
        const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'Laporan_Keuangan_' + new Date().getTime() + '.xlsx';
        document.body.appendChild(a);
        a.click();
        window.URL.revokeObjectURL(url);
        document.body.removeChild(a);
        
        logActivity('export_excel', 'Export laporan ke Excel');
        showToast('Laporan Excel berhasil diekspor!', 'success');
    } catch (e) {
        console.error('Export Excel failed:', e);
        showToast('Gagal mengekspor laporan Excel.', 'error');
    }
}

function exportToPDF() {
    if (!window.jspdf || !window.jspdf.jsPDF) { showToast('Library jsPDF tidak ditemukan!', 'error'); return; }
    const { jsPDF } = window.jspdf;
    
    const data = window.currentReportData;
    if (!data) { showToast('Buat laporan terlebih dahulu!', 'warning'); return; }
    
    showToast('Sedang menyiapkan PDF...', 'info');
    
    const logoBase64 = "data:image/png;base64,";
    
    try {
        generatePDFWithLogo(jsPDF, data, logoBase64);
    } catch (e) {
        console.error(e);
        showToast('Gagal membuat PDF.', 'error');
    }
}

function generatePDFWithLogo(jsPDF, data, logoImg) {
    const doc = new jsPDF('p', 'mm', 'a4');
    let currentY = 15;
    const pageWidth = doc.internal.pageSize.width;
    
    if (logoImg) {
        doc.addImage(logoImg, 'PNG', 15, currentY, 25, 25);
    }
    
    doc.setFontSize(16);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(30, 30, 30);
    doc.text("LPQ BAITUL MA'SUM", 45, currentY + 10);
    
    doc.setFontSize(10);
    doc.setFont('helvetica', 'normal');
    doc.text("Lembaga Pendidikan Al-Qur'an", 45, currentY + 16);
    doc.text("Surabaya", 45, currentY + 21);
    
    currentY += 30;
    
    doc.setDrawColor(46, 125, 50);
    doc.setLineWidth(1);
    doc.line(15, currentY, pageWidth - 15, currentY);
    currentY += 10;
    
    doc.setFontSize(12);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(0, 0, 0);
    
    const startMonth = data.startDate.toLocaleDateString('id-ID', { month: 'long', year: 'numeric' }).toUpperCase();
    const endMonth = data.endDate.toLocaleDateString('id-ID', { month: 'long', year: 'numeric' }).toUpperCase();
    let periodText = 'LAPORAN KEUANGAN BULAN ' + startMonth;
    if (startMonth !== endMonth) {
        periodText = 'LAPORAN KEUANGAN PERIODE ' + formatDate(data.startDate) + ' S/D ' + formatDate(data.endDate);
    }
    
    doc.text(periodText, pageWidth / 2, currentY, { align: 'center' });
    currentY += 10;
    
    const allTransactions = getData('lpq_transactions') || [];
    let priorBalance = 0;
    allTransactions.forEach(t => {
        const d = new Date(t.date);
        if (d < data.startDate) {
            if (t.type === 'income') priorBalance += Number(t.amount);
            else if (t.type === 'expense') priorBalance -= Number(t.amount);
        }
    });
    
    const tableBody = [];
    tableBody.push([
        formatDate(data.startDate),
        'SALDO SEBELUMNYA',
        '-',
        'Rp ' + formatCurrency(priorBalance),
        '',
        'Rp ' + formatCurrency(priorBalance)
    ]);
    
    let runningBalance = priorBalance;
    let periodIncome = 0;
    let periodExpense = 0;
    
    const chronologicalData = [...data.filtered].sort((a, b) => new Date(a.date) - new Date(b.date));
    
    chronologicalData.forEach(t => {
        const amount = Number(t.amount);
        let inc = '', exp = '';
        if (t.type === 'income') {
            inc = 'Rp ' + formatCurrency(amount);
            runningBalance += amount;
            periodIncome += amount;
        } else {
            exp = 'Rp ' + formatCurrency(amount);
            runningBalance -= amount;
            periodExpense += amount;
        }
        
        tableBody.push([
            formatDate(t.date),
            t.description || t.category,
            t.wallet || '-',
            inc,
            exp,
            'Rp ' + formatCurrency(runningBalance)
        ]);
    });
    
    if (logoImg && doc.GState) {
        doc.setGState(new doc.GState({opacity: 0.1}));
        doc.addImage(logoImg, 'PNG', 50, 100, 110, 110);
        doc.setGState(new doc.GState({opacity: 1}));
    }
    
    if (doc.autoTable) {
        doc.autoTable({
            startY: currentY,
            head: [['TANGGAL', 'KETERANGAN', 'SUMBER', 'PEMASUKAN', 'PENGELUARAN', 'SALDO']],
            body: tableBody,
            theme: 'grid',
            headStyles: {
                fillColor: [125, 183, 102],
                textColor: [255, 255, 255],
                fontStyle: 'bold',
                halign: 'center'
            },
            bodyStyles: {
                textColor: [0, 0, 0]
            },
            columnStyles: {
                0: { halign: 'center', cellWidth: 25 },
                1: { halign: 'left', cellWidth: 'auto' },
                2: { halign: 'center', cellWidth: 25 },
                3: { halign: 'right', cellWidth: 32 },
                4: { halign: 'right', cellWidth: 32 },
                5: { halign: 'right', cellWidth: 32, fontStyle: 'bold', fillColor: [235, 245, 235] }
            },
            alternateRowStyles: {
                fillColor: [250, 250, 250]
            }
        });
        
        currentY = doc.lastAutoTable.finalY + 15;
        
        doc.autoTable({
            startY: currentY,
            head: [['', 'PEMASUKAN PERIODE INI', 'PENGELUARAN PERIODE INI', 'SALDO AKHIR']],
            body: [
                ['SALDO BERSIH', 'Rp ' + formatCurrency(periodIncome), 'Rp ' + formatCurrency(periodExpense), 'Rp ' + formatCurrency(runningBalance)]
            ],
            theme: 'grid',
            headStyles: {
                fillColor: [125, 183, 102], 
                textColor: [255, 255, 255], 
                fontStyle: 'bold', 
                halign: 'center'
            },
            bodyStyles: {
                textColor: [0, 0, 0], 
                fontStyle: 'bold', 
                halign: 'center', 
                minCellHeight: 15, 
                valign: 'middle'
            },
            columnStyles: {
                0: { fillColor: [125, 183, 102], textColor: [255, 255, 255], fontStyle: 'bold', halign: 'center', valign: 'middle' }
            }
        });
    }
    
    doc.save('Laporan_Keuangan_' + new Date().getTime() + '.pdf');
    logActivity('export_pdf', 'Export laporan ke PDF');
    showToast('Laporan PDF berhasil diekspor!', 'success');

}